namespace ContosoUniversity.Tests.Models
{
    public class PaginatedListTests
    {
        [Fact]
        public void Constructor_SetsPageIndex()
        {
            var items = new List<string> { "a", "b" };
            var list = new PaginatedList<string>(items, 10, 2, 3);

            Assert.Equal(2, list.PageIndex);
        }

        [Fact]
        public void Constructor_CalculatesTotalPages()
        {
            var items = new List<string> { "a" };
            var list = new PaginatedList<string>(items, 10, 1, 3);

            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        }

        [Fact]
        public void Constructor_AddsItemsToList()
        {
            var items = new List<int> { 1, 2, 3 };
            var list = new PaginatedList<int>(items, 10, 1, 3);

            Assert.Equal(3, list.Count);
            Assert.Contains(1, list);
            Assert.Contains(2, list);
            Assert.Contains(3, list);
        }

        [Fact]
        public void HasPreviousPage_ReturnsFalse_OnFirstPage()
        {
            var list = new PaginatedList<int>(new List<int>(), 10, 1, 3);
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_ReturnsTrue_OnSecondPage()
        {
            var list = new PaginatedList<int>(new List<int>(), 10, 2, 3);
            Assert.True(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_ReturnsTrue_WhenNotOnLastPage()
        {
            var list = new PaginatedList<int>(new List<int>(), 10, 1, 3);
            Assert.True(list.HasNextPage); // TotalPages=4, PageIndex=1
        }

        [Fact]
        public void HasNextPage_ReturnsFalse_OnLastPage()
        {
            var list = new PaginatedList<int>(new List<int>(), 10, 4, 3);
            Assert.False(list.HasNextPage); // TotalPages=4, PageIndex=4
        }

        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();
            var result = PaginatedList<int>.Create(source, 2, 5);

            Assert.Equal(2, result.PageIndex);
            Assert.Equal(4, result.TotalPages);
            Assert.Equal(5, result.Count);
            Assert.Equal(6, result[0]); // Second page starts at 6
        }

        [Fact]
        public void Create_FirstPage_ReturnsFirstItems()
        {
            var source = Enumerable.Range(1, 10).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 3);

            Assert.Equal(3, result.Count);
            Assert.Equal(1, result[0]);
            Assert.Equal(2, result[1]);
            Assert.Equal(3, result[2]);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            var source = Enumerable.Range(1, 7).AsQueryable();
            var result = PaginatedList<int>.Create(source, 3, 3);

            Assert.Single(result); // Only 1 item on last page (7)
            Assert.Equal(7, result[0]);
        }

        [Fact]
        public void TotalPages_IsOne_WhenItemsFitOnOnePage()
        {
            var list = new PaginatedList<int>(new List<int> { 1, 2 }, 2, 1, 5);
            Assert.Equal(1, list.TotalPages);
        }
    }
}

