using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models
{
    public class ModelTests
    {
        [Fact]
        public void Person_FullName_ReturnsCombinedName()
        {
            var student = new Student { LastName = "Doe", FirstMidName = "John" };
            Assert.Equal("Doe, John", student.FullName);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_ReturnsFalse_WhenNull()
        {
            var model = new ErrorViewModel { RequestId = null };
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_ReturnsFalse_WhenEmpty()
        {
            var model = new ErrorViewModel { RequestId = "" };
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_ReturnsTrue_WhenSet()
        {
            var model = new ErrorViewModel { RequestId = "abc123" };
            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void Student_Properties_CanBeSet()
        {
            var date = DateTime.Parse("2020-01-01");
            var student = new Student
            {
                ID = 1,
                FirstMidName = "Jane",
                LastName = "Smith",
                EnrollmentDate = date
            };
            Assert.Equal(1, student.ID);
