using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void CanCreateContext()
        {
            using var context = TestDbContextFactory.Create();
            Assert.NotNull(context);
        }

        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            using var context = TestDbContextFactory.Create();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2020-01-01")
            };
            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.First(s => s.LastName == "Student");
            Assert.Equal("Test", retrieved.FirstMidName);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            using var context = TestDbContextFactory.Create();
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2000-01-01")
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var retrieved = context.Instructors.First(i => i.LastName == "Instructor");
            Assert.Equal("Test", retrieved.FirstMidName);
        }

        [Fact]
        public void CanAddAndRetrieveCourse()
        {
            using var context = TestDbContextFactory.Create();

            var dept = new Department
            {
                Name = "Test Dept",
                Budget = 100000,
                StartDate = DateTime.Parse("2020-01-01")
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 9999,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();

            var retrieved = context.Courses.First(c => c.CourseID == 9999);
            Assert.Equal("Test Course", retrieved.Title);
        }

        [Fact]
        public void CanAddAndRetrieveDepartment()
        {
            using var context = TestDbContextFactory.Create();
            var dept = new Department
            {
                Name = "Physics",
                Budget = 200000,
                StartDate = DateTime.Parse("2020-01-01")
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var retrieved = context.Departments.First(d => d.Name == "Physics");
            Assert.Equal(200000, retrieved.Budget);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            using var context = TestDbContextFactory.CreateWithData();

            var ca = context.CourseAssignments.First();
            Assert.True(ca.CourseID > 0);
            Assert.True(ca.InstructorID > 0);
        }

        [Fact]
        public void CanAddEnrollment()
        {
            using var context = TestDbContextFactory.CreateWithData();

            var enrollments = context.Enrollments.ToList();
            Assert.True(enrollments.Count >= 2);
        }

        [Fact]
        public void CanQueryStudentsWithEnrollments()
        {
            using var context = TestDbContextFactory.CreateWithData();

            var student = context.Students
                .Include(s => s.Enrollments)
                .First(s => s.LastName == "Alexander");

            Assert.NotNull(student.Enrollments);
            Assert.True(student.Enrollments.Count > 0);
        }

        [Fact]
        public void CanQueryCoursesWithDepartment()
        {
            using var context = TestDbContextFactory.CreateWithData();

            var course = context.Courses
                .Include(c => c.Department)
                .First(c => c.CourseID == 1050);

            Assert.NotNull(course.Department);
            Assert.Equal("Engineering", course.Department.Name);
        }

        [Fact]
        public void CanQueryInstructorWithOfficeAssignment()
        {
            using var context = TestDbContextFactory.CreateWithData();

            var instructor = context.Instructors
                .Include(i => i.OfficeAssignment)
                .First(i => i.LastName == "Abercrombie");

            Assert.NotNull(instructor.OfficeAssignment);
            Assert.Equal("Smith 17", instructor.OfficeAssignment.Location);
        }

        [Fact]
        public void CanAddNotification()
        {
            using var context = TestDbContextFactory.Create();
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test",
                CreatedAt = DateTime.Now,
                CreatedBy = "System",
                IsRead = false
            };
            context.Notifications.Add(notification);
            context.SaveChanges();

            Assert.Equal(1, context.Notifications.Count());
        }

        [Fact]
        public void CanDeleteStudent()
        {
            using var context = TestDbContextFactory.CreateWithData();
            var student = context.Students.First();
            context.Students.Remove(student);
            context.SaveChanges();

            Assert.Equal(2, context.Students.Count()); // Started with 3
        }

        [Fact]
        public void CanUpdateCourse()
        {
            using var context = TestDbContextFactory.CreateWithData();
            var course = context.Courses.First(c => c.CourseID == 1050);
            course.Title = "Advanced Chemistry";
            context.SaveChanges();

            var updated = context.Courses.First(c => c.CourseID == 1050);
            Assert.Equal("Advanced Chemistry", updated.Title);
        }
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.CreateWithData();
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index(null, null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal(3, model.Count);
        }

        [Fact]
        public void Index_SortsByLastName_DefaultOrder()
        {
            var result = _controller.Index(null, null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal("Alexander", model[0].LastName);
            Assert.Equal("Alonso", model[1].LastName);
            Assert.Equal("Anand", model[2].LastName);
        }

        [Fact]
        public void Index_SortsByLastNameDescending()
        {
            var result = _controller.Index("name_desc", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal("Anand", model[0].LastName);
        }

