using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextFactory.CreateWithData();
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewWithInstructorData()
        {
            var result = _controller.Index(null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.NotNull(model.Instructors);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_ShowsCourses()
        {
            var instructorId = _context.Instructors.First(i => i.LastName == "Abercrombie").ID;

            var result = _controller.Index(instructorId, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.NotNull(model.Courses);
            Assert.True(model.Courses.Any());
        }

        [Fact]
        public void Index_WithCourseId_ShowsEnrollments()
        {
            var instructorId = _context.Instructors.First(i => i.LastName == "Abercrombie").ID;

            var result = _controller.Index(instructorId, 1050);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.NotNull(model.Enrollments);
        }

        [Fact]
        public void Details_ReturnsInstructor_WhenFound()
        {
            var instructorId = _context.Instructors.First().ID;

            var result = _controller.Details(instructorId);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Instructor>(viewResult.Model);
        }

        [Fact]
        public void Details_ReturnsBadRequest_WhenIdNull()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ReturnsNotFound_WhenInstructorMissing()
        {
            var result = _controller.Details(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Create_GET_ReturnsView()
        {
            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Instructor>(viewResult.Model);
            Assert.NotNull(model.CourseAssignments);
            Assert.NotNull(_controller.ViewBag.Courses);
        }

        [Fact]
        public void Create_POST_RedirectsToIndex_WhenValid()
        {
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2020-01-01")
            };

            var result = _controller.Create(instructor, null!);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(3, _context.Instructors.Count());
        }

        [Fact]
        public void Create_POST_WithSelectedCourses_AddsCourseAssignments()
        {
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "WithCourses",
                HireDate = DateTime.Parse("2020-01-01")
            };
            var selectedCourses = new[] { "1050" };

            var result = _controller.Create(instructor, selectedCourses);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);

            var saved = _context.Instructors
                .Include(i => i.CourseAssignments)
                .First(i => i.LastName == "WithCourses");
            Assert.Single(saved.CourseAssignments);
        }

        [Fact]
        public void Create_POST_ReturnsView_WhenModelStateInvalid()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                HireDate = DateTime.Parse("2020-01-01")
            };

            var result = _controller.Create(instructor, null!);

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Edit_GET_ReturnsInstructor_WhenFound()
        {
            var instructorId = _context.Instructors.First().ID;

            var result = _controller.Edit(instructorId);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Instructor>(viewResult.Model);
            Assert.NotNull(_controller.ViewBag.Courses);
        }

        [Fact]
        public void Edit_GET_ReturnsBadRequest_WhenIdNull()
        {
            var result = _controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_ReturnsInstructor_WhenFound()
        {
            var instructorId = _context.Instructors.First().ID;

            var result = _controller.Delete(instructorId);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Instructor>(viewResult.Model);
        }

        [Fact]
        public void Delete_GET_ReturnsBadRequest_WhenIdNull()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_ReturnsNotFound_WhenInstructorMissing()
        {
            var result = _controller.Delete(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void DeleteConfirmed_RemovesInstructor()
        {
            // Create an instructor without department admin reference to avoid complexity
            var instructor = new Instructor
            {
                FirstMidName = "ToDelete",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2020-01-01")
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            // Add office assignment
            _context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = "Room 100"
            });
            _context.SaveChanges();

            var initialCount = _context.Instructors.Count();

            var result = _controller.DeleteConfirmed(instructor.ID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(initialCount - 1, _context.Instructors.Count());
        }

        [Fact]
        public void DeleteConfirmed_NullsDepartmentAdministrator()
        {
            var instructor = _context.Instructors.First(i => i.LastName == "Abercrombie");

            // Make sure the department references this instructor
            var dept = _context.Departments.First(d => d.InstructorID == instructor.ID);
            Assert.NotNull(dept);

            // Add office assignment (required by DeleteConfirmed)
            // Already exists from seed data

            _controller.DeleteConfirmed(instructor.ID);

            var updatedDept = _context.Departments.First(d => d.DepartmentID == dept.DepartmentID);
            Assert.Null(updatedDept.InstructorID);
        }

        [Fact]
        public void Index_InstructorsOrderedByLastName()
        {
            var result = _controller.Index(null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            var names = model.Instructors.Select(i => i.LastName).ToList();
            Assert.Equal(names.OrderBy(n => n).ToList(), names);
        }
    }
}
