using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers
{
    public class DepartmentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly DepartmentsController _controller;

        public DepartmentsControllerTests()
        {
            _context = TestDbContextFactory.CreateWithData();
            _controller = new DepartmentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsAllDepartments()
        {
            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Details_ReturnsDepartment_WhenFound()
        {
            var deptId = _context.Departments.First().DepartmentID;

            var result = _controller.Details(deptId);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Department>(viewResult.Model);
        }

        [Fact]
        public void Details_ReturnsBadRequest_WhenIdNull()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ReturnsNotFound_WhenDepartmentMissing()
        {
            var result = _controller.Details(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Create_GET_ReturnsView()
        {
            var result = _controller.Create();

            Assert.IsType<ViewResult>(result);
            Assert.NotNull(_controller.ViewBag.InstructorID);
        }

        [Fact]
        public void Create_POST_RedirectsToIndex_WhenValid()
        {
            var department = new Department
            {
                Name = "Physics",
                Budget = 200000,
                StartDate = DateTime.Parse("2020-01-01")
            };

            var result = _controller.Create(department);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(3, _context.Departments.Count());
        }

        [Fact]
        public void Create_POST_ReturnsView_WhenModelStateInvalid()
        {
            _controller.ModelState.AddModelError("Name", "Required");
            var department = new Department();

            var result = _controller.Create(department);

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Edit_GET_ReturnsDepartment_WhenFound()
        {
            var deptId = _context.Departments.First().DepartmentID;

            var result = _controller.Edit(deptId);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Department>(viewResult.Model);
            Assert.NotNull(_controller.ViewBag.InstructorID);
        }

        [Fact]
        public void Edit_GET_ReturnsBadRequest_WhenIdNull()
        {
            var result = _controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_GET_ReturnsNotFound_WhenDepartmentMissing()
        {
            var result = _controller.Edit(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_POST_RedirectsToIndex_WhenValid()
        {
            var dept = _context.Departments.AsNoTracking().First();
            dept.Name = "Updated Name";

            var result = _controller.Edit(dept);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_POST_ReturnsView_WhenModelStateInvalid()
        {
            _controller.ModelState.AddModelError("Name", "Required");
            var dept = _context.Departments.AsNoTracking().First();

            var result = _controller.Edit(dept);

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Delete_GET_ReturnsDepartment_WhenFound()
        {
            var deptId = _context.Departments.First().DepartmentID;

            var result = _controller.Delete(deptId);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Department>(viewResult.Model);
        }

        [Fact]
        public void Delete_GET_ReturnsBadRequest_WhenIdNull()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_ReturnsNotFound_WhenDepartmentMissing()
        {
            var result = _controller.Delete(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void DeleteConfirmed_RemovesDepartment()
        {
            // Use department without courses to avoid FK issues
            var dept = new Department
            {
                Name = "ToDelete",
                Budget = 1000,
                StartDate = DateTime.Parse("2020-01-01")
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var initialCount = _context.Departments.Count();

            var result = _controller.DeleteConfirmed(dept.DepartmentID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(initialCount - 1, _context.Departments.Count());
        }

        [Fact]
        public void Create_POST_SavesDepartmentWithInstructor()
        {
            var instructorId = _context.Instructors.First().ID;
            var department = new Department
            {
                Name = "History",
                Budget = 150000,
                StartDate = DateTime.Parse("2020-01-01"),
                InstructorID = instructorId
            };

            var result = _controller.Create(department);

            Assert.IsType<RedirectToActionResult>(result);
            var saved = _context.Departments.First(d => d.Name == "History");
            Assert.Equal(instructorId, saved.InstructorID);
        }
    }
}

