            {
                FirstMidName = "Empty",
                LastName = "Courses",
                HireDate = DateTime.Parse("2020-01-01")
            };

            var result = _controller.Create(instructor, Array.Empty<string>());

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_WithMultipleCourses()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Multi",
                LastName = "Course",
                HireDate = DateTime.Parse("2020-01-01")
            };

            var result = _controller.Create(instructor, new[] { "1050", "4022" });

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            var saved = _context.Instructors
                .Include(i => i.CourseAssignments)
                .First(i => i.LastName == "Course");
            Assert.Equal(2, saved.CourseAssignments.Count);
        }

        [Fact]
        public void Index_WithoutIds_ReturnsAllInstructors()
        {
            var result = _controller.Index(null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<ContosoUniversity.Models.SchoolViewModels.InstructorIndexData>(viewResult.Model);
            Assert.Null(model.Courses);
            Assert.Null(model.Enrollments);
        }

        [Fact]
        public void DeleteConfirmed_RemovesOfficeAssignment()
        {
            var instructor = new Instructor
            {
                FirstMidName = "HasOffice",
                LastName = "ToRemove",
                HireDate = DateTime.Parse("2020-01-01")
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            _context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = "Room 42"
            });
            _context.SaveChanges();

            _controller.DeleteConfirmed(instructor.ID);

            Assert.Null(_context.Instructors.Find(instructor.ID));
        }

        [Fact]
        public void Create_GET_PopulatesAssignedCourseData()
        {
            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            var courses = _controller.ViewBag.Courses as List<ContosoUniversity.Models.SchoolViewModels.AssignedCourseData>;
            Assert.NotNull(courses);
            Assert.Equal(2, courses.Count); // Our seed data has 2 courses
            Assert.All(courses, c => Assert.False(c.Assigned)); // None assigned to new instructor
        }

