            var result = _controller.Edit(instructorId);

            var courses = _controller.ViewBag.Courses as List<ContosoUniversity.Models.SchoolViewModels.AssignedCourseData>;
            Assert.NotNull(courses);
            Assert.Contains(courses, c => c.Assigned); // Has at least one assigned course
        }
    }
}
