using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerEdgeCaseTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _envMock;
        private readonly Mock<ILogger<CoursesController>> _loggerMock;

        public CoursesControllerEdgeCaseTests()
        {
            _context = TestDbContextFactory.CreateWithData();
            _envMock = new Mock<IWebHostEnvironment>();
            _envMock.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
            _envMock.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
            _loggerMock = new Mock<ILogger<CoursesController>>();
            _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Edit_POST_AcceptsValidImageUpload()
        {
            var course = _context.Courses.AsNoTracking().First(c => c.CourseID == 1050);
            _context.ChangeTracker.Clear();

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("material.jpg");
            fileMock.Setup(f => f.Length).Returns(2048);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Edit(course, fileMock.Object);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_POST_ReplacesExistingImage()
        {
            var course = _context.Courses.AsNoTracking().First(c => c.CourseID == 1050);
            course.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/old_image.jpg";
            _context.ChangeTracker.Clear();

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("new_image.png");
            fileMock.Setup(f => f.Length).Returns(1024);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Edit(course, fileMock.Object);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Contains("/Uploads/TeachingMaterials/", course.TeachingMaterialImagePath);
            Assert.DoesNotContain("old_image", course.TeachingMaterialImagePath);
        }

        [Fact]
        public void DeleteConfirmed_HandlesImageDeletion()
        {
            // Add a course with an image path
            var course = new Course
            {
                CourseID = 7777,
                Title = "WithImage",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/nonexistent.jpg"
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(7777);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Courses.Find(7777));
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void Create_POST_AcceptsAllValidImageExtensions(string extension)
        {
            var course = new Course
            {
                CourseID = 8000 + extension.GetHashCode() % 1000,
                Title = $"Test {extension}",
                Credits = 3,
                DepartmentID = 1
            };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns($"test{extension}");
            fileMock.Setup(f => f.Length).Returns(1024);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, fileMock.Object);

            Assert.IsType<RedirectToActionResult>(result);
        }

        [Fact]
        public void Create_POST_WithNullFile_Succeeds()
        {
            var course = new Course
            {
                CourseID = 9000,
                Title = "No Image",
                Credits = 3,
                DepartmentID = 1
            };

            var result = _controller.Create(course, null!);

            Assert.IsType<RedirectToActionResult>(result);
            Assert.Null(course.TeachingMaterialImagePath);
        }

        [Fact]
        public void Edit_POST_WithNullFile_PreservesExistingImage()
        {
            var course = _context.Courses.AsNoTracking().First(c => c.CourseID == 1050);
            course.TeachingMaterialImagePath = "/existing/path.jpg";
            _context.ChangeTracker.Clear();

            var result = _controller.Edit(course, null!);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_WebRootPathNull_UsesContentRootPath()
        {
            _envMock.Setup(e => e.WebRootPath).Returns((string)null!);

            var course = new Course
            {
                CourseID = 9001,
                Title = "FallbackPath",
                Credits = 3,
                DepartmentID = 1
            };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("test.jpg");
            fileMock.Setup(f => f.Length).Returns(1024);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, fileMock.Object);

            Assert.IsType<RedirectToActionResult>(result);
        }
    }
}

