using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerEdgeCaseTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerEdgeCaseTests()
        {
            _context = TestDbContextFactory.CreateWithData();
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Create_POST_WithEmptySelectedCourses_Succeeds()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Empty",
                LastName = "Courses",
                HireDate = DateTime.Parse("2020-01-01")
            };

            var result = _controller.Create(instructor, Array.Empty<string>());

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_WithMultipleCourses()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Multi",
                LastName = "Course",
                HireDate = DateTime.Parse("2020-01-01")
            };

            var result = _controller.Create(instructor, new[] { "1050", "4022" });

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            var saved = _context.Instructors
                .Include(i => i.CourseAssignments)
                .First(i => i.LastName == "Course");
            Assert.Equal(2, saved.CourseAssignments.Count);
        }

        [Fact]
        public void Index_WithoutIds_ReturnsAllInstructors()
        {
            var result = _controller.Index(null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<ContosoUniversity.Models.SchoolViewModels.InstructorIndexData>(viewResult.Model);
            Assert.Null(model.Courses);
            Assert.Null(model.Enrollments);
        }

        [Fact]
